package jp.terada.midnitelogger;
import android.content.*;import android.graphics.*;import android.view.*;import java.text.*;import java.util.*;
public class ChartView extends View{
 private List<float[]> p=new ArrayList<float[]>();private String title="";private long startMs,endMs;
 public ChartView(Context c){super(c);}
 public void set(List<float[]>x,String t,long s,long e){p=x;title=t;startMs=s;endMs=Math.max(e,s+1000L);invalidate();}
 protected void onDraw(Canvas c){super.onDraw(c);Paint a=new Paint(1);a.setColor(Color.DKGRAY);a.setTextSize(28);c.drawText(title,12,30,a);float l=60,t=48,r=getWidth()-12,b=getHeight()-58;a.setStyle(Paint.Style.STROKE);a.setColor(Color.LTGRAY);c.drawRect(l,t,r,b,a);labels(c,a,l,r,b);if(p.size()<2){a.setStyle(Paint.Style.FILL);a.setColor(Color.DKGRAY);a.setTextSize(24);c.drawText("表示データがありません",30,100,a);return;}float min=Float.MAX_VALUE,max=-Float.MAX_VALUE;for(float[]q:p){min=Math.min(min,q[1]);max=Math.max(max,q[1]);}if(max==min){max+=1;min-=1;}Path path=new Path();for(int i=0;i<p.size();i++){float[]q=p.get(i);long tm=startMs+(long)q[0]*1000L;float ratio=(float)(tm-startMs)/(float)(endMs-startMs);ratio=Math.max(0f,Math.min(1f,ratio));float x=l+(r-l)*ratio,y=b-(b-t)*(q[1]-min)/(max-min);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}a.setColor(Color.BLUE);a.setStrokeWidth(3);a.setStyle(Paint.Style.STROKE);c.drawPath(path,a);a.setStyle(Paint.Style.FILL);a.setColor(Color.DKGRAY);a.setTextSize(20);c.drawText(String.format(Locale.US,"%.2f",max),2,t+10,a);c.drawText(String.format(Locale.US,"%.2f",min),2,b,a);}
 private void labels(Canvas c,Paint a,float l,float r,float b){SimpleDateFormat f=new SimpleDateFormat("MM/dd HH:mm",Locale.US);String s=f.format(new Date(startMs)),m=f.format(new Date(startMs+(endMs-startMs)/2)),e=f.format(new Date(endMs));a.setStyle(Paint.Style.FILL);a.setColor(Color.DKGRAY);a.setTextSize(18);c.drawText(s,l,b+28,a);c.drawText(m,(l+r-a.measureText(m))/2,b+28,a);c.drawText(e,r-a.measureText(e),b+28,a);}
}
